cd /workspace/scratch && python3 - <<'EOF'
import numpy as np, sys
sys.path.insert(0,'/workspace/candidate'); import solve as S
from fitlib import simulate, basis
t8=np.linspace(0,8,401); ics=np.array([[0.5,0.3],[-0.8,0.6],[0.9,-0.4],[-0.3,-0.9]])
g=np.linspace(-1.5,1.5,21); G=np.array([(a,b) for a in g for b in g]); B=basis(G)
def field_err(C,Ct): return np.linalg.norm((C-Ct).T@B.T)/np.linalg.norm(Ct.T@B.T)
def roll_err(C,Ct):
    es=[]
    for z0 in ics:
        try:
            Yt=simulate(Ct,z0,t8,1e-10,1e-12,False); Y=simulate(C,z0,t8,1e-9,1e-11,False)
            es.append(np.linalg.norm(Y-Yt)/np.linalg.norm(Yt))
        except Exception: es.append(9)
    return np.mean(es)
CtB=np.zeros((10,2)); CtB[2,0]=1.0; CtB[1,1]=-1.0; CtB[2,1]=-0.2
rng2=np.random.default_rng(99)
for i in [3,4,5,6,7,8,9]: CtB[i,1]=rng2.normal(0,0.15)
for rel in [0.08,0.12]:
    d=f'/workspace/scratch/hn/B{rel}'
    t,data,meta=S.load_case(d)
    ntr=np.load(d+'/train.npy').shape[0]; val=data[ntr:]
    print('rel',rel)
    for win in [21,31,41,51]:
        Cw=S.weak_stlsq(t,data,win,3,0.02,8)
        mask=np.abs(Cw)>=1e-6
        Cn,chi,ok=S.nls_fit(t,data,Cw,mask,max_nfev=80)
        Cn=S.np.where(np.abs(Cn)<1e-6,0,Cn)
        print(f' win{win} K{int(np.sum(Cn!=0))} field {field_err(Cn,CtB):.4f} roll {roll_err(Cn,CtB):.4f}')
